# Root-owned staged source-controls entry. Runs preflight, then bounded r10 controls.
[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$StageRoot,
  [Parameter(Mandatory)][string]$PlanPath,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ExpectedPlanSha256,
  [Parameter(Mandatory)][string]$PreflightPath,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ExpectedPreflightSha256,
  [Parameter(Mandatory)][string]$OutputPath,
  [Parameter(Mandatory)][string]$GateReceiptPath
)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Require([bool]$ok,[string]$message){if(-not $ok){throw $message}}
function Full([string]$path){return [IO.Path]::GetFullPath($path)}
function Hash([string]$path){return (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Read-BoundedJson([string]$path){$item=Get-Item -LiteralPath $path -Force;Require (($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0 -and $item.Length -le 2097152) "bounded JSON rejected: $path";return [IO.File]::ReadAllText($item.FullName)|ConvertFrom-Json}
function Write-FreshJson([string]$path,[object]$value){$full=Full $path;Require (-not(Test-Path -LiteralPath $full)) "receipt must be fresh: $full";$parent=Split-Path -Parent $full;if(-not(Test-Path -LiteralPath $parent -PathType Container)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$full.$([guid]::NewGuid().ToString('N')).tmp";$bytes=[Text.Encoding]::UTF8.GetBytes(($value|ConvertTo-Json -Depth 12)+"`r`n");$stream=[IO.File]::Open($tmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Move($tmp,$full)}
$stage=Full $StageRoot;$planFile=Full $PlanPath;$preflight=Full $PreflightPath;$output=Full $OutputPath;$gate=Full $GateReceiptPath
Require (Test-Path -LiteralPath $stage -PathType Container) "stage missing: $stage";Require (Test-Path -LiteralPath $planFile -PathType Leaf) "plan missing: $planFile";Require ($planFile -ceq (Full (Join-Path $stage 'one-run-plan-r8.json'))) 'controls plan must be staged one-run-plan-r8.json';Require (Test-Path -LiteralPath $preflight -PathType Leaf) 'production preflight missing';Require ([IO.Path]::GetFileName($preflight) -ceq 'entry-native-r8.ps1') 'production preflight filename mismatch';Require ((Hash $preflight) -ceq $ExpectedPreflightSha256.ToLowerInvariant()) 'exact production preflight SHA-256 mismatch'
$plan=Read-BoundedJson $planFile;$pins=Read-BoundedJson (Join-Path $stage 'source-pins-r8.json');$actualPlanSha=Hash $planFile;Require ($actualPlanSha -ceq $ExpectedPlanSha256.ToLowerInvariant()) 'exact plan SHA-256 mismatch';Require ([string]$pins.sourcePlanSha256 -ceq $actualPlanSha) 'source pin plan SHA-256 mismatch';Require ([string]$plan.schema -eq 'sr0-display-selfjob-v4-fresh-one-run-r8') 'plan schema mismatch';Require (-not [bool]$plan.qualificationClaim -and [int]$plan.nativeActions -eq 0) 'controls gate requires non-native plan';Require ([int64]$plan.aggregateJobMemoryLimitBytes -eq 1073741824) '1GiB aggregate limit missing';Require ([int]$plan.deadlineSeconds -eq 900 -and [int]$plan.pollSeconds -eq 1) 'native bounds mismatch';Require ([bool]$plan.noActivate -and [bool]$plan.noResources) 'interaction guards missing'
$preflightText=& $preflight -StageRoot $stage | Out-String;$preflightSucceeded=$?;Require $preflightSucceeded 'staged production preflight failed';$preflightReceipt=$preflightText|ConvertFrom-Json;Require ([string]$preflightReceipt.status -eq 'passed-source-preflight' -and [int]$preflightReceipt.nativeActions -eq 0 -and [bool]$preflightReceipt.qualificationClaim -eq $false) 'preflight receipt status invalid';Require ([string]$preflightReceipt.planSha256 -ceq $actualPlanSha) 'preflight plan SHA-256 mismatch'
$control=Full (Join-Path $stage 'run-source-controls-r8.ps1');$helper=Full ([string]$plan.drainHelperPath);Require (Test-Path -LiteralPath $control -PathType Leaf) 'staged controls runner missing';Require (Test-Path -LiteralPath $helper -PathType Leaf) 'staged drain helper missing';Require (@($plan.requiredControlReceipts).Count -eq 1) 'exactly one production control receipt required';$expectedOutput=Full (Join-Path ([string]$plan.controlReceiptRoot) ([string]$plan.requiredControlReceipts[0]));Require ($output -ceq $expectedOutput) 'controls output must equal plan-required receipt path';Require (-not(Test-Path -LiteralPath $output)) 'controls receipt must be fresh';$work=Full (Join-Path (Split-Path -Parent $output) 'drain-controls-work-r10b');if(-not(Test-Path -LiteralPath $work -PathType Container)){[IO.Directory]::CreateDirectory($work)|Out-Null}
& $control -StageRoot $stage -PlanPath $planFile -OutputPath $output;$controlsSucceeded=$?;Require $controlsSucceeded 'staged source controls failed';$receipt=Read-BoundedJson $output;Require ([string]$receipt.kind -eq 'sr0-display-workload-drain-controls-r10' -and [string]$receipt.status -eq 'passed-source-controls' -and [bool]$receipt.nativeQualificationClaim -eq $false) 'r10 controls receipt invalid';Require ([string]$receipt.helperSha256 -ceq ([string]$plan.sourcePins.drainHelper).ToLowerInvariant()) 'controls helper pin mismatch';$controlSha=Hash $output
$gateValue=[ordered]@{schema='sr0-display-selfjob-v4-staged-controls-gate-r10b';status='passed-source-controls-gate';stageRoot=$stage;planPath=$planFile;planSha256=$actualPlanSha;preflightPath=$preflight;preflightStatus=[string]$preflightReceipt.status;controlsReceiptPath=$output;controlsReceiptSha256=$controlSha;requiredControlReceipts=@($plan.requiredControlReceipts);nativeActions=0;qualificationClaim=$false;checkedAt=[DateTimeOffset]::UtcNow.ToString('o')};Write-FreshJson $gate $gateValue;$gateValue|ConvertTo-Json -Depth 8
